        #region Helper Methods - FASE 2.1

        /// <summary>
        /// 🎯 Ottiene grip di riferimento per un circuito
        /// </summary>
        public static float GetReferenceGrip(string circuitName)
        {
            var physicsData = GetCircuitPhysicsData(circuitName);
            return physicsData?.ReferenceGrip ?? 1.0f;
        }

        /// <summary>
        /// 📏 Ottiene lunghezza ufficiale del circuito
        /// </summary>
        public static float GetCircuitLength(string circuitName)
        {
            var physicsData = GetCircuitPhysicsData(circuitName);
            return physicsData?.CircuitLength ?? 0f;
        }

        /// <summary>
        /// 🌬️ Ottiene drag aerodinamico di riferimento per il circuito
        /// </summary>
        public static float GetReferenceAeroDrag(string circuitName)
        {
            var physicsData = GetCircuitPhysicsData(circuitName);
            return physicsData?.ReferenceAeroDrag ?? 100.0f;
        }

        /// <summary>
        /// 📊 FASE 2.1: Stampa riepilogo parametri calcolati per tutti i circuiti
        /// </summary>
        public static void PrintParametersSummary()
        {
            Console.WriteLine("📊 PARAMETRI LEGACY CALCOLATI:");
            foreach (var circuit in GetAvailableCircuits())
            {
                var physics = GetCircuitPhysicsData(circuit);
                if (physics != null)
                {
                    Console.WriteLine($"   🎯 {circuit.PadRight(15)} - Grip: {physics.ReferenceGrip:F3}, " +
                                    $"Smoothness: {physics.CircuitSmoothness:F1}, " +
                                    $"Length: {physics.CircuitLength:F0}m, " +
                                    $"AeroDrag: {physics.ReferenceAeroDrag:F1}");
                }
            }
        }

        #endregion
    }
